function uuidv4() {
  if (globalThis.crypto && typeof globalThis.crypto.randomUUID === 'function') return globalThis.crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}
const input = $json || {};
const body = input.body && typeof input.body === 'object' ? input.body : input;
const headers = input.headers || {};
const header = (name) => {
  const v = headers[name] ?? headers[name.toLowerCase()] ?? headers[name.toUpperCase()];
  return v == null ? '' : String(v).trim();
};
const authHeader = header('authorization');
const accessToken = /^Bearer\s+(.+)$/i.test(authHeader) ? authHeader.replace(/^Bearer\s+/i, '').trim() : '';
const correlationId = String(body.correlation_id || header('x-correlation-id') || uuidv4()).trim();
const idempotencyKey = String(body.idempotency_key || `portal:transcript.request:${uuidv4()}`).trim();
const institutionId = String(body.institution_id || body.institutionId || '').trim();
const campusId = String(body.campus_id || body.campusId || '').trim();
const studentId = String(body.student_id || body.studentId || '').trim();
const recipientEmail = String(body.recipient_email || body.recipientEmail || '').trim().toLowerCase();
const purpose = String(body.purpose || 'Official academic transcript request').trim();
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const valid = Boolean(
  accessToken &&
  uuidRe.test(correlationId) &&
  uuidRe.test(institutionId) &&
  uuidRe.test(campusId) &&
  uuidRe.test(studentId) &&
  idempotencyKey &&
  recipientEmail.includes('@')
);
return [{
  json: {
    valid,
    access_token: accessToken,
    correlation_id: correlationId,
    idempotency_key: idempotencyKey,
    institution_id: institutionId,
    campus_id: campusId,
    student_id: studentId,
    recipient_email: recipientEmail,
    purpose,
    submitted_at: new Date().toISOString(),
    validation_error: valid ? null : {
      code: 'VALIDATION_REQUEST_ENVELOPE_REQUIRED',
      message: 'A valid login, academic scope, student, recipient email and idempotency key are required.'
    }
  }
}];

const request = $('Normalize Transcript Request').item.json;
const raw = $json || {};
const statusCode = Number(raw.statusCode || raw.status || 0);
const body = raw.body !== undefined ? raw.body : raw;
const userId = body && typeof body === 'object' ? (body.id || body.user?.id || null) : null;
const authenticated = Boolean(userId && (!statusCode || statusCode < 400));
return [{json:{...request, authenticated, auth_user_id:userId, auth_response_status:statusCode || (authenticated ? 200 : 401)}}];

const context = $('Classify Supabase User').item.json;
const raw = $json || {};
const statusCode = Number(raw.statusCode || raw.status || 0);
const body = raw.body !== undefined ? raw.body : raw;
const rpc = Array.isArray(body) ? (body[0] || {}) : (body || {});
const transportFailed = Boolean(raw.error || raw.errorMessage || (statusCode >= 400 && !rpc.success));
const success = rpc.success === true && !transportFailed;
const error = rpc.error || {};
let responseCode = 422;
if (transportFailed && statusCode >= 500) responseCode = 502;
else if (String(error.code || '').startsWith('AUTH_')) responseCode = 403;
else if (String(error.code || '').includes('NOT_FOUND')) responseCode = 404;
else if (String(error.code || '').includes('IDEMPOTENCY')) responseCode = 409;
return [{json:{
  ...context,
  request_rpc_success: success,
  request_rpc: rpc,
  request_data: rpc.data || {},
  response_code: success ? 200 : responseCode,
  public_error: success ? null : {
    code: error.code || (transportFailed ? 'TRANSCRIPT_REQUEST_SERVICE_UNAVAILABLE' : 'TRANSCRIPT_REQUEST_FAILED'),
    message: error.message || 'The transcript request could not be completed.',
    retryable: Boolean(error.retryable || (transportFailed && statusCode >= 500))
  }
}}];

const x=$json;
const d=x.request_data.existing_document || {};
const delivery=x.request_data.existing_delivery || {};
return [{json:{
 success:true,
 operation:'transcript.request.create',
 correlation_id:x.correlation_id,
 idempotency_key:x.idempotency_key,
 data:{
   transcript_request_id:x.request_data.transcript_request_id,
   reference_number:x.request_data.reference_number,
   verification_code:x.request_data.verification_code || null,
   status:x.request_data.status,
   transcript_document_id:d.transcript_document_id || d.id || null,
   google_doc_id:d.google_doc_id || null,
   pdf_drive_file_id:d.pdf_drive_file_id || null,
   pdf_file_url:d.pdf_file_url || null,
   delivery_status:delivery.delivery_status || null,
   document_reused:true
 },
 warnings:[]
}}];

const context=$('Classify Transcript Request').item.json;
const raw=$json||{};
const statusCode=Number(raw.statusCode||raw.status||0);
const body=raw.body!==undefined?raw.body:raw;
const rpc=Array.isArray(body)?(body[0]||{}):(body||{});
const success=rpc.success===true && !(raw.error||raw.errorMessage||(statusCode>=400&&!rpc.success));
const error=rpc.error||{};
return [{json:{
 ...context,
 model_rpc_success:success,
 transcript_model:rpc.data||{},
 public_error:success?null:{
   code:error.code||'TRANSCRIPT_MODEL_FAILED',
   message:error.message||'The transcript academic record could not be loaded.',
   retryable:Boolean(error.retryable||statusCode>=500)
 },
 response_code: success?200:(String(error.code||'').startsWith('AUTH_')?403:(String(error.code||'').includes('NOT_FOUND')?404:422))
}}];

const x=$json;
const m=x.transcript_model||{};
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const terms=Array.isArray(m.terms)?m.terms:[];
const courseRows=terms.map(term=>{
  const courses=Array.isArray(term.courses)?term.courses:[];
  const rows=courses.map(c=>`<tr><td>${esc(c.course_code)}</td><td>${esc(c.course_title)}</td><td class="num">${esc(c.credit_hours)}</td><td class="num">${esc(c.total_score)}</td><td class="center">${esc(c.letter_grade)}</td><td class="num">${esc(c.grade_point)}</td><td>${esc(c.outcome_code)}</td></tr>`).join('');
  const sr=term.semester_result||{};
  return `<div class="term"><h3>${esc(term.term_name)} (${esc(term.term_code)}) — ${esc(term.academic_year)}</h3><table><thead><tr><th>Course</th><th>Title</th><th>Credits</th><th>Score</th><th>Grade</th><th>GP</th><th>Outcome</th></tr></thead><tbody>${rows||'<tr><td colspan="7">No published courses</td></tr>'}</tbody></table><div class="term-summary"><span>Attempted credits: <b>${esc(sr.attempted_credits)}</b></span><span>Earned credits: <b>${esc(sr.earned_credits)}</b></span><span>GPA: <b>${esc(sr.gpa)}</b></span><span>Standing: <b>${esc(sr.standing_code)}</b></span></div></div>`;
}).join('');
const cumulative=m.cumulative||{};
const institution=m.institution||{};
const campus=m.campus||{};
const student=m.student||{};
const program=m.program||{};
const logo=institution.logo_url?`<img class="logo" src="${esc(institution.logo_url)}" alt="Institution logo">`:`<div class="logo-fallback">${esc((institution.code||'SIS').slice(0,6))}</div>`;
const html=`<!doctype html><html><head><meta charset="utf-8"><style>
@page{size:A4;margin:18mm}body{font-family:Arial,sans-serif;color:#172033;font-size:10.5pt;line-height:1.35}header{display:flex;align-items:center;border-bottom:3px solid #243b64;padding-bottom:12px;margin-bottom:16px}.logo{width:72px;height:72px;object-fit:contain;margin-right:16px}.logo-fallback{width:72px;height:72px;border:2px solid #243b64;display:flex;align-items:center;justify-content:center;font-weight:700;margin-right:16px}.title h1{font-size:20pt;margin:0;color:#172b4d}.title p{margin:3px 0}.badge{margin-left:auto;text-align:right}.badge strong{display:block;font-size:12pt}.section{border:1px solid #c8d1df;padding:10px;margin:10px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:6px 18px}.label{color:#5b6678}.term{page-break-inside:avoid;margin-top:16px}.term h3{background:#e9eef6;padding:7px;margin:0}table{border-collapse:collapse;width:100%;font-size:9.3pt}th,td{border:1px solid #aeb9c8;padding:5px}th{background:#243b64;color:#fff}.num{text-align:right}.center{text-align:center}.term-summary,.summary{display:flex;gap:18px;flex-wrap:wrap;background:#f3f6fa;padding:7px}.footer{margin-top:18px;border-top:1px solid #aeb9c8;padding-top:10px;font-size:8.5pt;color:#4b5565}.watermark{font-weight:700;color:#9a3412}.verify{word-break:break-all}
</style></head><body>
<header>${logo}<div class="title"><h1>${esc(institution.name)}</h1><p>${esc(campus.name)}${campus.city?', '+esc(campus.city):''}</p><p>ACADEMIC TRANSCRIPT</p></div><div class="badge"><strong>${esc(m.reference_number)}</strong><span>Issue date: ${esc(m.issue_date)}</span></div></header>
<div class="section grid"><div><span class="label">Student name:</span> <b>${esc(student.full_name)}</b></div><div><span class="label">Student number:</span> <b>${esc(student.student_number)}</b></div><div><span class="label">Program:</span> ${esc(program.name)} (${esc(program.code)})</div><div><span class="label">Level:</span> ${esc(program.level_name)}</div><div><span class="label">Student status:</span> ${esc(student.status)}</div><div><span class="label">Academic model:</span> ${esc(program.academic_model)}</div></div>
${courseRows||'<div class="section">No published academic record is available.</div>'}
<div class="summary"><span>Total attempted credits: <b>${esc(cumulative.attempted_credits)}</b></span><span>Total earned credits: <b>${esc(cumulative.earned_credits)}</b></span><span>CGPA: <b>${esc(cumulative.cgpa)}</b></span><span>Academic standing: <b>${esc(cumulative.standing_code)}</b></span></div>
<div class="section"><b>Verification code:</b> ${esc(m.verification_code)}</div>
<div class="footer"><div class="watermark">CONTROLLED PILOT / DEMONSTRATION DOCUMENT</div><p>${esc(m.disclaimer||'')}</p><p>This transcript was generated from published academic records. Alteration invalidates the document.</p></div>
</body></html>`;
const safeRef=String(m.reference_number||'transcript').replace(/[^A-Za-z0-9_-]+/g,'-');
const docName=`${safeRef} - ${student.student_number||'student'} - Transcript`;
const pdfName=`${safeRef}-${student.student_number||'student'}.pdf`;
const boundary='sis-05-transcript-boundary';
const metadata={name:docName,mimeType:'application/vnd.google-apps.document'};
if(x.drive_folder_id) metadata.parents=[x.drive_folder_id];
const multipart=`--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify(metadata)}\r\n--${boundary}\r\nContent-Type: text/html; charset=UTF-8\r\n\r\n${html}\r\n--${boundary}--`;
return [{json:{...x, transcript_html:html, google_doc_multipart_body:multipart, multipart_boundary:boundary, google_doc_file_name:docName, pdf_file_name:pdfName}}];

const ctx=$('Populate Transcript Google Docs Template').item.json;
const raw=$json||{};
const status=Number(raw.statusCode||raw.status||0);
let body=raw.body!==undefined?raw.body:raw;
if(typeof body==='string'){try{body=JSON.parse(body);}catch{}}
if(body&&typeof body.data==='object'){body=body.data}
const files=Array.isArray(body?.files)?body.files:[];
const file=files[0]||null;
const failed=Boolean(raw.error||raw.errorMessage||status>=400||!file?.id);
return [{json:{...ctx,google_doc_created:!failed,google_doc_id:file?.id||null,google_doc_url:file?.webViewLink||null,external_error:failed?{code:'GOOGLE_DOC_RESOLUTION_FAILED',message:'The transcript Google Doc was created but its Drive file ID could not be resolved.',retryable:status===429||status>=500,stage:'google_doc_resolve'}:null}}];

const ctx=$('Classify Google Doc Creation').item.json;
const item=$input.first();
const hasPdf=Boolean(item.binary&&item.binary.pdf&&Number(item.binary.pdf.fileSize||0)!==0);
return [{json:{...ctx,pdf_exported:hasPdf,external_error:hasPdf?null:{code:'GOOGLE_PDF_EXPORT_FAILED',message:'The transcript PDF could not be exported.',retryable:true,stage:'pdf_export'}},binary:item.binary||{}}];

const ctx=$('Compute Transcript PDF SHA256').item.json;
const raw=$json||{};
const status=Number(raw.statusCode||raw.status||0);
let body=raw.body!==undefined?raw.body:raw;
if(typeof body==='string'){try{body=JSON.parse(body);}catch{}}
if(body&&typeof body.data==='object'){body=body.data}
const files=Array.isArray(body?.files)?body.files:[];
const file=files[0]||null;
const failed=Boolean(raw.error||raw.errorMessage||status>=400||!file?.id);
return [{json:{...ctx,pdf_uploaded:!failed,pdf_drive_file_id:file?.id||null,pdf_initial_url:file?.webViewLink||file?.webContentLink||null,external_error:failed?{code:'GOOGLE_PDF_RESOLUTION_FAILED',message:'The transcript PDF was uploaded but its Drive file ID could not be resolved.',retryable:status===429||status>=500,stage:'pdf_resolve'}:null}}];

const ctx=$('Classify PDF Upload').item.json;
const raw=$json||{};
const status=Number(raw.statusCode||raw.status||0);
let body=raw.body!==undefined?raw.body:raw;
if(typeof body==='string'){try{body=JSON.parse(body);}catch{}}
if(body&&typeof body.data==='object'){body=body.data}
const failed=Boolean(raw.error||raw.errorMessage||status>=400);
const url=body?.webViewLink||body?.webContentLink||ctx.pdf_initial_url||(ctx.pdf_drive_file_id?`https://drive.google.com/file/d/${ctx.pdf_drive_file_id}/view`:null);
return [{json:{...ctx,artifact_ready:!failed,pdf_file_url:url,pdf_drive_file_id:body?.id||ctx.pdf_drive_file_id,external_error:failed?{code:'GOOGLE_PDF_METADATA_FAILED',message:'The transcript PDF was uploaded but its Drive metadata could not be finalized.',retryable:status===429||status>=500,stage:'pdf_metadata'}:null}}];

const ctx=$('Build Transcript Artifact').item.json;
const raw=$json||{};
const status=Number(raw.statusCode||raw.status||0);
let body=raw.body!==undefined?raw.body:raw;
if(typeof body==='string'){try{body=JSON.parse(body);}catch{}}
if(body&&typeof body.data==='object'&&body.success===undefined){body=body.data}
const rpc=Array.isArray(body)?(body[0]||{}):(body||{});
const success=rpc.success===true&&!(raw.error||raw.errorMessage||(status>=400&&!rpc.success));
const error=rpc.error||{};
return [{json:{...ctx,document_recorded:success,record_rpc:rpc,record_data:rpc.data||{},external_error:success?null:{code:error.code||'TRANSCRIPT_DOCUMENT_RECORD_FAILED',message:error.message||'The transcript document could not be registered.',retryable:Boolean(error.retryable||status>=500),stage:'document_record'}}}];

const x=$json||{};
const req=(x.request_data&&x.request_data.transcript_request_id)?x.request_data.transcript_request_id:null;
const err=x.external_error||x.public_error||{code:'TRANSCRIPT_EXTERNAL_FAILURE',message:'The transcript could not be completed.',retryable:false,stage:'unknown'};
return [{json:{...x, transcript_request_id:req, failure_error:err, response_code:err.retryable?502:422}}];

const x=$('Prepare Transcript Failure').item.json;
return [{json:{
 success:false,
 operation:'transcript.delivery.complete',
 correlation_id:x.correlation_id,
 idempotency_key:x.idempotency_key,
 error:{
   code:x.failure_error.code||'TRANSCRIPT_EXTERNAL_FAILURE',
   message:x.failure_error.message||'The transcript could not be completed.',
   retryable:Boolean(x.failure_error.retryable)
 }
}}];
